/** Igor command-line options, keyed by their longest name */
export interface IgorCliOptions {
  /** password to use for testing SSH connections */
  password?: string | number;
  /** username to use for testing SSH connections */
  username?: string | number;
  /** hostname to use for testing SSH connections */
  hostname?: string | number;
  /** path to a file containing variables (deprecated) */
  options?: string | number;
  /** show less output from commands (aliases: q) */
  quiet?: boolean;
  /** output errors to standard error as a json struct */
  jsonErrors?: boolean;
  /** yyp project file */
  project?: string | number;
  /** path to the runtime to use (aliases: rp) */
  runtimePath?: string | number;
  /** url to the rss feed containing runtimes (aliases: ru) */
  runtimeUrl?: string | number;
  /** VM or YYC (aliases: r) */
  runtime?: string | number;
  /** folder to use as a build cache */
  cache?: string | number;
  /** project config to build */
  config?: string | number;
  /** folder to store temporary files created during build */
  temp?: string | number;
  /** package type used for the build */
  packagetype?: string | number;
  /** path to the user folder for the user doing the build (aliases: uf) */
  user?: string | number;
  /** number of cores AssetCompiler should use */
  j?: string | number;
  /** output filename */
  of?: string | number;
  /** target filename */
  tf?: string | number;
  /** overall timeout for test including build (aliases: t) */
  timeout?: string | number;
  /**  (aliases: wt) */
  'waittime=VALUE time for test to wait once inside main loop'?:
    string | number;
  /** the name of the device to run on (aliases: d) */
  device?: string | number;
  /** the path to a licence file, if not specified we'll look in the user folder (aliases: lf) */
  licencefile?: string | number;
  /** the path to a devices.json file, if not specified we'll look in the user folder (aliases: df) */
  devicefile?: string | number;
  /** comma separated list of targets for tests, e.g. Windows|Local,HTML5|selenium:firefox */
  target?: string | number;
  /** the name of the remote worker to do the build on (aliases: w) */
  worker?: string | number;
  /** does a debug build */
  debug?: boolean;
  /** export yydebug as part of compile (aliases: g) */
  yydebug?: boolean;
  /** sets the port the debugger will try to connect on */
  dbgp?: string | number;
  /** path to a file containing remote target options (deprecated) */
  targetOptions?: string | number;
  /** Destination folder to copy a framework to on macOS remote */
  destFolder?: string | number;
  /** output file for JSON with timing stats */
  timingStats?: string | number;
  /** output file for function stats */
  functionStats?: string | number;
  /** input file for fnames (needed for coverage info) */
  fnames?: string | number;
  /** parent project to be used while testing */
  parentproject?: string | number;
  /** increase the amount of verbose output (aliases: v) */
  verbose?: boolean;
  /** tell asset compiler to ignore cache (aliases: ic) */
  ignorecache?: boolean;
  /** pass option to the asset compiler (aliases: ac) */
  assetCompiler?: string | number;
  /** Device identifier for target device */
  targetDevice?: string | number;
  /** Steam SDK Directory */
  ssdk?: string | number;
  /** force Igor to think console is redirected (aliases: cr) */
  consoleRedirect?: boolean;
  /** runtime modules to download (aliases: m) */
  modules?: string | number;
  /** address and port of the mqtt server */
  mqtt?: string | number;
  /** api access key (aliases: ak) */
  accessKey?: string | number;
  /** path to the prefabs library folder (aliases: pf) */
  prefabs?: string | number;
  /** path to the project tool to be used (aliases: pt) */
  projectool?: string | number;
  /** install (if necessary) and launch built package on target */
  launch?: boolean;
  /** runs a prebuild version of the game (doesn't build) (aliases: nb) */
  nobuild?: boolean;
}

